import{_ as e,o as t,c as n,a3 as o}from"./chunks/framework.BLaSdaBb.js";const g=JSON.parse('{"title":"Get Athanor on Android","description":"","frontmatter":{},"headers":[],"relativePath":"download.md","filePath":"download.md"}'),r={name:"download.md"};function i(s,a,l,h,d,p){return t(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="get-athanor-on-android" tabindex="-1">Get Athanor on Android <a class="header-anchor" href="#get-athanor-on-android" aria-label="Permalink to &quot;Get Athanor on Android&quot;">​</a></h1><p>Athanor runs in any browser at <a href="https://play.athanor.games/" target="_blank" rel="noreferrer">play.athanor.games</a>, and that needs nothing installed. The Android build is the same game with the screen to itself: no browser chrome, and it keeps playing when the signal does not.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>Take the <strong>arm64-v8a</strong> build unless you know otherwise. Every Android phone made in roughly the last decade uses it.</p><table tabindex="0"><thead><tr><th>Build</th><th>For</th></tr></thead><tbody><tr><td><a href="/builds/athanor-arm64-v8a.apk.html">athanor-arm64-v8a.apk</a></td><td><strong>Almost certainly this one</strong>: any modern phone or tablet</td></tr><tr><td><a href="/builds/athanor-armeabi-v7a.apk.html">athanor-armeabi-v7a.apk</a></td><td>Older 32-bit devices</td></tr><tr><td><a href="/builds/athanor-x86_64.apk.html">athanor-x86_64.apk</a></td><td>Emulators, and Chromebooks that run Android apps</td></tr></tbody></table><p>There are three because a phone only needs the code for its own chip, and one file holding all of them would be half again as large.</p><h2 id="installing-it" tabindex="-1">Installing it <a class="header-anchor" href="#installing-it" aria-label="Permalink to &quot;Installing it&quot;">​</a></h2><p>Android will not install a file from outside its store without being told to. That is a sensible default, and it takes one tap to allow.</p><ol><li>Open the downloaded file. Android asks whether your browser may install unknown apps.</li><li>Allow it, and confirm the install.</li><li>You may be offered a scan by Play Protect. Let it. It is checking a file it has not seen before, which is exactly what it is for.</li></ol><div class="tip custom-block"><p class="custom-block-title">Updating</p><p>Install a newer build straight over the old one. Your campaigns and settings stay where they are. Nothing is lost, and you do not need to uninstall first.</p></div><h2 id="if-the-install-is-refused" tabindex="-1">If the install is refused <a class="header-anchor" href="#if-the-install-is-refused" aria-label="Permalink to &quot;If the install is refused&quot;">​</a></h2><p><strong>&quot;App not installed&quot;</strong> almost always means an older Athanor is already on the phone from before the builds were signed properly. Uninstall it and install again. Your saves live in the app, so back up first if you have a campaign worth keeping: sign in on the <a href="https://play.athanor.games/" target="_blank" rel="noreferrer">browser version</a> and let it mirror your save to your account, then sign in again after reinstalling.</p><p><strong>Nothing happens when you open the file.</strong> Some browsers hide the download rather than opening it. Look in your Downloads app or notification shade and open it from there.</p><h2 id="on-iphone-and-ipad" tabindex="-1">On iPhone and iPad <a class="header-anchor" href="#on-iphone-and-ipad" aria-label="Permalink to &quot;On iPhone and iPad&quot;">​</a></h2><p>There is no App Store build yet. Until there is, <strong>the browser is the way</strong>. <a href="https://play.athanor.games/" target="_blank" rel="noreferrer">play.athanor.games</a> is the whole game, not a demo or a cut-down version. Save it to your Home Screen and it opens like an app:</p><ol><li>Open <a href="https://play.athanor.games/" target="_blank" rel="noreferrer">play.athanor.games</a> in Safari.</li><li>Tap <strong>Share</strong>, then <strong>Add to Home Screen</strong>.</li><li>Open it from there and it runs full screen, without Safari&#39;s bars.</li></ol><p>Turn the phone to landscape, which is what the game is built for. Sign in if you want the campaign kept to your account rather than to that browser.</p><h2 id="keeping-a-campaign-across-devices" tabindex="-1">Keeping a campaign across devices <a class="header-anchor" href="#keeping-a-campaign-across-devices" aria-label="Permalink to &quot;Keeping a campaign across devices&quot;">​</a></h2><p>Sign in with Google, in the app or in the browser, and your campaign is mirrored to your account. Sign in on the other device and it is offered back to you, so a phone and a laptop can carry the same Great Work between them. See <a href="/guide/saving.html">Saving Your Campaign</a>.</p>',19)])])}const u=e(r,[["render",i]]);export{g as __pageData,u as default};
